<?php
namespace Database\Seeders;
use App\Enums\UserRole; use App\Models\Service; use App\Models\User; use Illuminate\Database\Seeder;
class DatabaseSeeder extends Seeder { public function run(): void { $admin=User::firstOrCreate(['email'=>'admin@example.com'],['name'=>'Demo Admin','password'=>'password123','role'=>UserRole::Admin]);$customer=User::firstOrCreate(['email'=>'customer@example.com'],['name'=>'Demo Customer','password'=>'password123','role'=>UserRole::Customer]);$providerUser=User::firstOrCreate(['email'=>'provider@example.com'],['name'=>'Demo Provider','password'=>'password123','role'=>UserRole::Provider]);$provider=$providerUser->provider()->firstOrCreate([],['bio'=>'Demo provider for portfolio testing.','timezone'=>'Asia/Tehran','is_active'=>true]);$consultation=Service::firstOrCreate(['name'=>'Consultation'],['description'=>'General appointment consultation.','duration_minutes'=>30,'is_active'=>true]);$therapy=Service::firstOrCreate(['name'=>'Extended Session'],['description'=>'Longer appointment session.','duration_minutes'=>60,'is_active'=>true]);$provider->services()->syncWithoutDetaching([$consultation->id=>['price'=>500000,'is_active'=>true],$therapy->id=>['price'=>900000,'is_active'=>true]]);foreach([1,2,3,4,5] as $day){$provider->availabilities()->firstOrCreate(['day_of_week'=>$day,'start_time'=>'09:00:00','end_time'=>'17:00:00']);} } }
